import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

__global__ void __launch_bounds__(256) tanh_kernel_vec4(const float4* __restrict__ input,
                                  float4* __restrict__ output,
                                  int64_t n_vec4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 8
    for (int64_t i = idx; i < n_vec4; i += stride) {
        float4 in = __ldg(&input[i]);
        output[i] = make_float4(tanhf(in.x), tanhf(in.y), tanhf(in.z), tanhf(in.w));
    }
}
__global__ void __launch_bounds__(256) tanh_kernel_scalar(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 8
    for (int64_t i = idx; i < n; i += stride) {
        output[i] = tanhf(__ldg(&input[i]));
    }
}

torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto output = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();
    if (n % 4 == 0) {
        int64_t n_vec4 = n / 4;
        int min_grid_size = 0;
        int block_size = 256;
        cudaOccupancyMaxPotentialBlockSize(&min_grid_size, &block_size,
                                            tanh_kernel_vec4, 0, 0);
        if (block_size <= 0) block_size = 256;
        int64_t needed_blocks = (n_vec4 + block_size - 1) / block_size;
        int blocks = (int)std::min<int64_t>(needed_blocks, (int64_t)min_grid_size * 32);
        if (blocks < 1) blocks = 1;
        tanh_kernel_vec4<<<blocks, block_size>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(output.data_ptr<float>()),
            n_vec4
        );
    } else {
        int min_grid_size = 0;
        int block_size = 256;
        cudaOccupancyMaxPotentialBlockSize(&min_grid_size, &block_size,
                                            tanh_kernel_scalar, 0, 0);
        if (block_size <= 0) block_size = 256;
        int64_t needed_blocks = (n + block_size - 1) / block_size;
        int blocks = (int)std::min<int64_t>(needed_blocks, (int64_t)min_grid_size * 32);
        if (blocks < 1) blocks = 1;
        tanh_kernel_scalar<<<blocks, block_size>>>(
            x_contig.data_ptr<float>(),
            output.data_ptr<float>(),
            n
        );
    }
    return output;
}
"""
cpp_source = "torch::Tensor tanh_cuda(torch::Tensor x);"
tanh_ext = load_inline(
    name="tanh_ext",
    cpp_sources=cpp_source,
    cuda_sources=tanh_source,
    functions=["tanh_cuda"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.tanh_ext = tanh_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_ext.tanh_cuda(x)
